/*
 * minimal replace.h for building the vendored talloc library.
 *
 * talloc normally ships inside the Samba build system, where replace.h
 * is generated by configure.  For LinuxDroid-PRoot we vendor talloc so
 * that both desktop and Android NDK builds are self-contained (no system
 * libtalloc-dev / pkg-config required).  This header provides the small
 * set of feature-detection macros and standard includes that talloc.c
 * relies on.
 *
 * talloc is licensed under the GNU Lesser General Public License v3+.
 */
#ifndef LINUXDROID_REPLACE_H
#define LINUXDROID_REPLACE_H

#ifndef _GNU_SOURCE
#define _GNU_SOURCE 1
#endif

/* Standard C / POSIX headers that talloc.c expects to be visible. */
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <strings.h>
#include <errno.h>
#include <limits.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/param.h>

/* glibc / Bionic both provide sys/auxv.h and getauxval(). */

/* GCC supports __attribute__((constructor)) on glibc and Bionic. */
#define HAVE_CONSTRUCTOR_ATTRIBUTE 1

/* stdarg.h provides a proper va_copy() on both toolchains. */
#define HAVE_VA_COPY 1

#ifndef MIN
#define MIN(a, b) ((a) < (b) ? (a) : (b))
#endif
#ifndef MAX
#define MAX(a, b) ((a) > (b) ? (a) : (b))
#endif

/* The rest are intentionally left undefined:
 *   HAVE_CONSTRUCTOR_ATTRIBUTE / HAVE_PRAGMA_INIT  -> handled below
 *   HAVE_VA_COPY / HAVE___VA_COPY                 -> fallback used
 *   HAVE_VALGRIND_H / HAVE_VALGRIND_MEMCHECK_H    -> no valgrind on Android
 */

#ifndef HAVE_BOOL
#define HAVE_BOOL 1
#endif

#endif /* LINUXDROID_REPLACE_H */
